const notFound = () => `${pageHero('Nie znaleziono strony','Wróćmy na kort.','Wybierz stronę główną lub interesujący Cię temat z menu.',`<a class="button" href="#/">Strona główna</a>`)}`;
const routes = {'':home,platforma:platform,budowa:courtsPage,korty:courtsPage,autonomia:autonomy,sklep:shop,gracze:players,realizacje:projects,wiedza:knowledge,'o-nas':about,rozwiazania:solutions,kontakt:contact,opinie:opinions,pobierz:download};
const routeTitles = {'':'Twój klub. Twój system.',platforma:'Platforma',budowa:'Korty',korty:'Korty',autonomia:'Korty autonomiczne',sklep:'Sklep partnerski',gracze:'Dla graczy',realizacje:'Realizacje',wiedza:'Poradniki','o-nas':'O nas',rozwiazania:'Rozwiązania',kontakt:'Kontakt',opinie:'Opinie',pobierz:'Pobierz aplikację'};
let firstRender=true;
function route(){
 if(location.hash && !location.hash.startsWith('#/'))return;
 const key=decodeURIComponent(location.hash.replace(/^#\/?/,''));
 const render=routes[key] || (key.startsWith('artykul-')?()=>article(Number(key.slice(8))):notFound);
 $('#main').innerHTML=render();
 document.title=`NeoPadel — ${routeTitles[key] || 'Wiedza'}`;
 document.body.dataset.page=key||'home';
 $$('.nav-links>a').forEach(a=>a.setAttribute('aria-current',a.hash===`#/${key}`?'page':'false'));
 closeMenu();
 if(!firstRender){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
 firstRender=false;
 enhance();
}
// Scroll-driven motion for the home page: reveals, the event flow stage and the video loops.
let observers=[];
function enhance(){
 observers.forEach(o=>o.disconnect());observers=[];shotsManual=false;pauseShots();
 const still=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const reveal=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');reveal.unobserve(e.target);}}),{rootMargin:'0px 0px -12% 0px'});
 $$('[data-reveal]').forEach(el=>reveal.observe(el));observers.push(reveal);
 const stage=$('.flow-stage');
 if(stage){const steps=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)setStep(stage,Number(e.target.dataset.step));}),{rootMargin:matchMedia('(max-width:760px)').matches?'-64% 0px -28% 0px':'-45% 0px -45% 0px'});$$('.flow-step').forEach(el=>steps.observe(el));observers.push(steps);}
 const videos=new IntersectionObserver(es=>es.forEach(e=>{const v=e.target;if(e.isIntersecting&&!still){v.play().catch(()=>{});}else v.pause();}),{threshold:.15});
 $$('[data-loop]').forEach(v=>videos.observe(v));observers.push(videos);
 $$('[data-network]').forEach(c=>network(c,still));
 mountConfigurator();
 motion(still);
 const tabs=$('.shot-tabs');
 if(tabs&&!still){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)startShots();else pauseShots();}),{threshold:.35});io.observe($('#shot-panel'));observers.push(io);}
 const timer=$('[data-timer]');
 if(timer){let t=0;const tick=setInterval(()=>{if(!document.body.contains(timer))return clearInterval(tick);if($('.support-ui.in')){t++;timer.textContent=`${String(t/60|0).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;}},1000);}
}
// Reach: players as points; waves leave the centre and light every point they pass.
function network(canvas,still){
 const ctx=canvas.getContext('2d');let w,h,nodes=[],links=[],raf=0,visible=false,t0=performance.now();
 function setup(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);w=r.width;h=r.height;canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);
  const n=Math.round(Math.max(45,Math.min(110,w*h/9000)));let seed=7;const rnd=()=>(seed=(seed*16807)%2147483647)/2147483647;
  nodes=Array.from({length:n},()=>{const a=rnd()*Math.PI*2,rr=Math.sqrt(rnd())*.52;return{x:w/2+Math.cos(a)*rr*w,y:h/2+Math.sin(a)*rr*h*1.1,r:1.2+rnd()*2.4,lit:0}});
  nodes.forEach(p=>p.dist=Math.hypot((p.x-w/2)/w,(p.y-h/2)/h));
  links=[];nodes.forEach((p,i)=>nodes.slice(i+1).forEach(q=>{const dd=Math.hypot(p.x-q.x,p.y-q.y);if(dd<Math.min(w,h)*.16)links.push([p,q,dd])}));}
 function frame(now){const time=(now-t0)/1000,period=3.2;ctx.clearRect(0,0,w,h);
  const waves=still?[]:[0,1,2].map(k=>((time/period+k/3)%1)*.75);
  nodes.forEach(p=>{const hit=waves.some(wv=>Math.abs(wv-p.dist)<.018);p.lit=still?.6:Math.max(p.lit*.965,hit?1:0)});
  links.forEach(([p,q])=>{const a=.05+(p.lit+q.lit)*.18;ctx.strokeStyle=`rgba(196,103,203,${a})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()});
  waves.forEach(wv=>{ctx.strokeStyle=`rgba(196,103,203,${(1-wv/.75)*.35})`;ctx.lineWidth=1.2;ctx.beginPath();ctx.ellipse(w/2,h/2,wv*w,wv*h,0,0,Math.PI*2);ctx.stroke()});
  nodes.forEach(p=>{const g=p.lit;ctx.fillStyle=`rgba(${Math.round(150+g*90)},${Math.round(110+g*20)},${Math.round(220+g*20)},${.35+g*.65})`;ctx.beginPath();ctx.arc(p.x,p.y,p.r+g*1.6,0,Math.PI*2);ctx.fill();if(g>.3){ctx.fillStyle=`rgba(226,92,232,${g*.18})`;ctx.beginPath();ctx.arc(p.x,p.y,p.r*5*g,0,Math.PI*2);ctx.fill()}});
  if(visible&&!still)raf=requestAnimationFrame(frame);}
 setup();frame(performance.now());
 const io=new IntersectionObserver(es=>es.forEach(e=>{visible=e.isIntersecting;cancelAnimationFrame(raf);if(visible&&!still)raf=requestAnimationFrame(frame)}));io.observe(canvas);observers.push(io);
 addEventListener('resize',()=>{if(document.body.contains(canvas)){setup();frame(performance.now())}},{passive:true});
}
// Screens rotate on their own while in view, until the visitor picks a tab.
let shotTimer=null,shotsManual=false;
function startShots(){if(shotsManual||shotTimer)return;$('.shot-tabs')?.classList.add('auto');shotTimer=setInterval(()=>{const t=$$('.shot-tabs [data-tab]');if(!t.length)return stopShots();const i=t.findIndex(b=>b.getAttribute('aria-selected')==='true');selectTab(t[(i+1)%t.length],true);},4500);}
function pauseShots(){clearInterval(shotTimer);shotTimer=null;$('.shot-tabs')?.classList.remove('auto');}
function stopShots(){shotsManual=true;pauseShots();}
// Court configurator (court3d.js): model and turf buttons drive the 3D scene.
let court3d=null;
function mountConfigurator(){
 const box=$('#court3d');if(!box)return;
 court3d=window.mountCourt3d?window.mountCourt3d(box):null;if(!court3d)box.classList.add('nogl');
 const pick=(attr,fn)=>$$(`[${attr}]`).forEach(b=>b.addEventListener('click',()=>{$$(`[${attr}]`).forEach(x=>x.setAttribute('aria-checked',String(x===b)));court3d&&court3d[fn](b.getAttribute(attr));}));
 pick('data-court','setModel');pick('data-turf','setTurf');
}
// Linear-style details: cursor-following edge glow on cards, gentle 3D tilt with a moving sheen on screens.
let motionBound=false;
function motion(still){
 $$('.tile,.k-model,.k-turf,.config-panel,.k-auto,.chat,.call-card,.week-card,.need').forEach(el=>el.classList.add('glow'));
 if(!still)$$('.mini-shot,.k-hero-photo').forEach(el=>{el.setAttribute('data-tilt','');if(!el.querySelector('.sheen')){const sh=document.createElement('i');sh.className='sheen';el.appendChild(sh);}});
 if(motionBound)return;motionBound=true;
 document.addEventListener('pointermove',e=>{
  const g=e.target.closest&&e.target.closest('.glow');if(g){const r=g.getBoundingClientRect();g.style.setProperty('--mx',`${e.clientX-r.left}px`);g.style.setProperty('--my',`${e.clientY-r.top}px`);}
  const t=e.target.closest&&e.target.closest('[data-tilt]');
  $$('[data-tilt].tilting').forEach(x=>{if(x!==t){x.classList.remove('tilting');x.style.removeProperty('--rx');x.style.removeProperty('--ry');}});
  if(t){const r=t.getBoundingClientRect(),px=(e.clientX-r.left)/r.width-.5,py=(e.clientY-r.top)/r.height-.5;t.classList.add('tilting');t.style.setProperty('--rx',`${(-py*7).toFixed(2)}deg`);t.style.setProperty('--ry',`${(px*9).toFixed(2)}deg`);t.style.setProperty('--sx',`${(px+.5)*100}%`);}
 },{passive:true});
}
let countTimer=null;
function setStep(stage,n){
 if(stage.dataset.step===String(n))return;
 stage.dataset.step=n;
 $$('.flow-step').forEach(el=>el.classList.toggle('active',Number(el.dataset.step)===n));
 const count=$('[data-count]',stage);clearInterval(countTimer);count.textContent='14';stage.classList.remove('full');
 if(n===3){let c=14;countTimer=setInterval(()=>{c++;count.textContent=c;if(c>=16){clearInterval(countTimer);stage.classList.add('full');}},520);}
}
function closeMenu(){$('#nav-links').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$$('.nav-more').forEach(x=>x.open=false)}
$('#menu-toggle').addEventListener('click',()=>{const open=$('#nav-links').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
const dialog=$('#onboarding');let trigger=null;
function openDialog(content){$('#dialog-content').innerHTML=content;$('#dialog-content').classList.remove('step-in');void $('#dialog-content').offsetWidth;$('#dialog-content').classList.add('step-in');$('#onboarding').classList.toggle('wide',content.includes('need-grid'));if(!dialog.open)dialog.showModal();$('#dialog-title')?.focus();}
function onboard(){openDialog(`<span class="eyebrow">Zacznij z NeoPadel</span><h2 id="dialog-title" tabindex="-1">Czego potrzebujesz?</h2><p>Wybierz, od czego zaczynamy. Zawsze możesz wrócić i zmienić wybór.</p><div class="need-grid"><button class="need" data-need="system" style="--i:0"><span class="need-vis vis-system"><img class="v-panel" src="${asset('panel/ekran-dzien.webp')}" alt=""><span class="v-phone"><img src="${asset('film/app-start.jpg')}" alt=""></span></span><b>System dla klubu</b><span>Społeczność, rezerwacje i płatności w jednym miejscu. Panel dla Ciebie, aplikacja dla graczy.</span></button><button class="need" data-need="korty" style="--i:1"><span class="need-vis vis-korty"><img class="v-court" src="${asset('korty/render-panorama.jpg')}" alt=""></span><b>Budowa kortów</b><span>Projekt, produkcja i montaż kortów w całej Polsce. Model, nawierzchnia, oświetlenie, hala.</span></button><button class="need" data-need="oba" style="--i:2"><span class="need-vis vis-oba"><img class="v-court" src="${asset('korty/render-super.jpg')}" alt=""><span class="v-phone"><img src="${asset('film/app-start.jpg')}" alt=""></span></span><b>Jedno i drugie</b><span>Nowy klub od zera: korty i system od pierwszego dnia, z jednym partnerem.</span></button></div><p class="note">Prototyp: ten widok nie zakłada konta i nie wysyła danych.</p>`,true)}
function needPath(n){
 if(n==='system')return openDialog(`<span class="eyebrow">System dla klubu</span><h2 id="dialog-title" tabindex="-1">Na jakim etapie jest Twój klub?</h2><p>Zacznij od ścieżki dopasowanej do Twojej sytuacji.</p><div class="choices"><button class="choice" data-stage="dziala">Prowadzę klub <span>Chcę zarządzać rezerwacjami i budować społeczność graczy.</span></button><button class="choice" data-stage="planuje">Planuję otwarcie <span>Buduję klub lub przygotowuję go do startu.</span></button></div><button class="dialog-back" data-reset>Zmień wybór</button>`);
 if(n==='korty')return openDialog(`<span class="eyebrow">Budowa kortów</span><h2 id="dialog-title" tabindex="-1">Gdzie ma stanąć kort?</h2><p>Model, nawierzchnię i oświetlenie dobieramy do miejsca. Obejrzyj modele w konfiguratorze albo od razu umów konsultację.</p><div class="dialog-actions"><a class="button" href="#/korty" data-close>Otwórz konfigurator</a><a class="button ghost-btn" href="#/kontakt" data-close>Umów konsultację</a></div><button class="dialog-back" data-reset>Zmień wybór</button>`);
 return openDialog(`<span class="eyebrow">Jedno i drugie</span><h2 id="dialog-title" tabindex="-1">Klub od zera, z jednym partnerem.</h2><ol class="steps"><li>Konsultacja: lokalizacja, skala i plan obiektu.</li><li>Korty, nawierzchnia, oświetlenie i hala.</li><li>System rezerwacji, płatności i społeczność od dnia otwarcia.</li></ol><div class="dialog-actions"><a class="button" href="#/kontakt" data-close>Porozmawiaj z NeoPadel</a><a class="button ghost-btn" href="#/korty" data-close>Zobacz korty</a></div><button class="dialog-back" data-reset>Zmień wybór</button>`);
}
function showStage(stage){openDialog(`<span class="eyebrow">Podgląd · ${stage==='dziala'?'Istniejący klub':'Planowany klub'}</span><h2 id="dialog-title" tabindex="-1">${stage==='dziala'?'Przenieś klub do NeoPadel.':'Przygotuj klub do otwarcia.'}</h2><p>Proponowana ścieżka wdrożenia:</p><ol class="steps"><li>Konto właściciela i potwierdzenie adresu e-mail.</li><li>Dane klubu, lokalizacja i korty.</li><li>Konfiguracja panelu przed uruchomieniem rezerwacji.</li></ol><a class="button" href="#/kontakt" data-close>Porozmawiaj z NeoPadel ${arrow}</a><br><button class="dialog-back" data-reset>Zmień etap</button><p class="note">To projekt ścieżki onboardingu. Rejestracja wymaga osobnego wdrożenia i podłączenia do API.</p>`)}
function login(){openDialog(`<span class="eyebrow">Panel klubu</span><h2 id="dialog-title" tabindex="-1">Wróć do swojego klubu.</h2><p>Otwórz adres panelu otrzymany podczas wdrożenia Twojego klubu. Jeśli go nie masz, skontaktuj się z zespołem NeoPadel.</p><a class="button" href="mailto:office@neopadel.eu">Uzyskaj pomoc ${arrow}</a><p class="note">Podgląd landingu — logowanie do panelu nie jest tutaj podłączone.</p>`)}
function selectTab(button,auto=false){$$('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1;});$$('[data-pane]').forEach(p=>p.classList.toggle('on',p.dataset.pane===button.dataset.tab));if(!auto)stopShots();}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;
 if(b.hasAttribute('data-onboard')){trigger=b;onboard();}
 if(b.hasAttribute('data-login')){trigger=b;login();}
 if(b.hasAttribute('data-stage'))showStage(b.dataset.stage);
 if(b.hasAttribute('data-need'))needPath(b.dataset.need);
 if(b.hasAttribute('data-reset'))onboard();
 if(b.hasAttribute('data-close'))dialog.close();
 if(b.hasAttribute('data-tab'))selectTab(b);
 if(b.matches('a[href^="#/"]'))closeMenu();
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();if(e.target.matches('[role=tab]')&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role=tab]');const index=tabs.indexOf(e.target);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[next]);tabs[next].focus();}});
document.addEventListener('click',e=>{if(!e.target.closest('.nav-more'))$$('.nav-more').forEach(x=>x.open=false)});
dialog.addEventListener('close',()=>{trigger?.focus();});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',route);route();
